// Bygger URL till Enhetsregisterets oppdateringsfeed.
// Tomt eller saknat cursor-värde betyder att flödet aldrig har kört förut.
const rows = $input.all();
const cursor = String(rows[0]?.json?.value ?? '').trim();
const base = 'https://data.brreg.no/enhetsregisteret/api/oppdateringer/enheter';

let url;
if (cursor === '') {
  // Första körningen: hämta allt från och med igår (dygnet trunkerat till datum).
  const since = new Date(Date.now() - 24 * 60 * 60 * 1000);
  const day = since.toISOString().slice(0, 10);
  url = base + '?dato=' + day + 'T00:00:00.000Z' + '&size=500';
} else {
  url = base + '?oppdateringsid=' + cursor + '&size=500';
}

return [{ json: { url } }];

// Läser händelserna direkt från Flatten events, inte från Postgres-svaret.
const events = $('Flatten events').all();
const byOrgnr = new Map();

for (const item of events) {
  const e = item.json ?? {};
  const orgnr = e.organisasjonsnummer;
  if (!orgnr) continue;

  const isDeleted = e.endringstype === 'Sletting' || e.endringstype === 'Fjerning';
  const existing = byOrgnr.get(orgnr);
  if (existing) {
    existing.deleted = existing.deleted || isDeleted;
  } else {
    byOrgnr.set(orgnr, { organisasjonsnummer: orgnr, deleted: isDeleted });
  }
}

if (byOrgnr.size === 0) return [];

return [...byOrgnr.values()].map(v => ({ json: v }));

// HTTP-noden behåller ordningen 1:1 när neverError är på, så vi parar ihop på index.
const sources = $('Unique orgnr').all();
const items = $input.all();

const FORM_MAP = {
  AS: 'aktiebolag',
  ASA: 'publikt_aktiebolag',
  ENK: 'enskild_firma',
  NUF: 'filial',
};

const out = [];

for (let i = 0; i < items.length; i++) {
  const res = items[i].json ?? {};
  const src = sources[i]?.json ?? {};
  const b = res.body ?? {};
  const orgnr = src.organisasjonsnummer ?? b.organisasjonsnummer ?? null;
  const deleted = src.deleted === true;
  const statusCode = Number(res.statusCode ?? 200);

  // Borttaget hos BRREG, eller raderat utan kropp att mappa: bara statusuppdatering.
  if (statusCode === 404 || statusCode === 410 || (deleted && !b.organisasjonsnummer)) {
    out.push({ json: { orgnr, statusOnly: true } });
    continue;
  }

  // Övriga fel ska synas i felflödet, inte tystas.
  if (statusCode >= 400) {
    throw new Error('BRREG-anropet misslyckades för orgnr ' + orgnr + ' med statuskod ' + statusCode);
  }

  const orgFormRaw = b.organisasjonsform?.kode ?? null;
  const orgForm = FORM_MAP[orgFormRaw] ?? orgFormRaw?.toLowerCase() ?? null;

  const status = b.slettedato
    ? 'upphörd'
    : b.konkurs
      ? 'konkurs'
      : (b.underAvvikling || b.underTvangsavviklingEllerTvangsopplosning)
        ? 'under_avveckling'
        : 'aktiv';

  out.push({
    json: {
      orgnr: b.organisasjonsnummer ?? orgnr,
      name: b.navn ?? null,
      org_form: orgForm,
      org_form_raw: orgFormRaw,
      nace_code: b.naeringskode1?.kode ?? null,
      founded: b.stiftelsesdato ?? null,
      employees: b.antallAnsatte ?? null,
      municipality: b.forretningsadresse?.kommune ?? null,
      address: b.forretningsadresse ? JSON.stringify(b.forretningsadresse) : null,
      status,
      website: b.hjemmeside ?? null,
      raw: JSON.stringify(b),
      statusOnly: false,
    },
  });
}

return out;

// API-parametern oppdateringsid är större än eller lika med, därför max + 1.
// Överlappning är ofarlig eftersom company_events.event_id är primärnyckel.
const events = $('Flatten events').all();
if (events.length === 0) return [];

let max = 0;
for (const item of events) {
  const id = Number(item.json?.oppdateringsid);
  if (Number.isFinite(id) && id > max) max = id;
}

// Inget giltigt id hittat: rör inte cursorn.
if (max === 0) return [];

return [{ json: { next: String(max + 1) } }];
